CREATE TABLE users(id text PRIMARY KEY,email text UNIQUE NOT NULL,salt text NOT NULL,password text NOT NULL,identity text NOT NULL,verified integer NOT NULL DEFAULT 0,code text,code_expires bigint,code_attempts integer NOT NULL DEFAULT 0);
CREATE TABLE sessions(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,expires bigint NOT NULL,mfa_until bigint NOT NULL DEFAULT 0);
CREATE TABLE limits(bucket text PRIMARY KEY,count integer NOT NULL,expires bigint NOT NULL);
CREATE TABLE inbox(id text PRIMARY KEY,email text NOT NULL,code text NOT NULL,created bigint NOT NULL);
CREATE TABLE agreements(user_id text REFERENCES users ON DELETE CASCADE,version text NOT NULL,accepted bigint NOT NULL,health_consent boolean NOT NULL,PRIMARY KEY(user_id,version));
CREATE TABLE documents(id bigserial PRIMARY KEY,owner_id text NOT NULL REFERENCES users ON DELETE CASCADE,kind text NOT NULL,data jsonb NOT NULL,shared boolean NOT NULL DEFAULT false,parent_id bigint REFERENCES documents ON DELETE CASCADE);
CREATE INDEX documents_owner_kind ON documents(owner_id,kind);
CREATE INDEX documents_date ON documents((data->>'date'));
CREATE TABLE follows(from_id text REFERENCES users ON DELETE CASCADE,to_id text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(from_id,to_id),CHECK(from_id<>to_id));
CREATE TABLE likes(user_id text REFERENCES users ON DELETE CASCADE,post_id bigint REFERENCES documents ON DELETE CASCADE,PRIMARY KEY(user_id,post_id));
CREATE TABLE factors(user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE,secret text,pending text,pending_expires bigint,used bigint,recovery jsonb NOT NULL DEFAULT '[]',attempts integer NOT NULL DEFAULT 0,locked_until bigint NOT NULL DEFAULT 0);
CREATE TABLE factor_keys(key text PRIMARY KEY,owner_id text REFERENCES users ON DELETE CASCADE,expires bigint NOT NULL,registered boolean NOT NULL);
CREATE TABLE nonces(nonce text PRIMARY KEY,expires bigint NOT NULL);
CREATE TABLE media(id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES users ON DELETE CASCADE,size integer NOT NULL,created bigint NOT NULL);
CREATE TABLE deletion_tombstones(account_hash text PRIMARY KEY,deleted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_gc(id uuid PRIMARY KEY,queued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE security_events(id bigserial PRIMARY KEY,kind text NOT NULL,account_hash text,created timestamptz NOT NULL DEFAULT now());
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE documents FORCE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON documents FOR SELECT USING(owner_id=current_setting('app.user_id',true) OR shared OR (kind IN('message','request') AND data->>'recipientId'=current_setting('app.user_id',true)));
CREATE POLICY documents_insert ON documents FOR INSERT WITH CHECK(owner_id=current_setting('app.user_id',true));
CREATE POLICY documents_update ON documents FOR UPDATE USING(owner_id=current_setting('app.user_id',true) OR (kind IN('message','request') AND data->>'recipientId'=current_setting('app.user_id',true))) WITH CHECK(owner_id=current_setting('app.user_id',true) OR (kind IN('message','request') AND data->>'recipientId'=current_setting('app.user_id',true)));
CREATE POLICY documents_delete ON documents FOR DELETE USING(owner_id=current_setting('app.user_id',true) OR (kind IN('message','request') AND data->>'recipientId'=current_setting('app.user_id',true)));
CREATE UNIQUE INDEX profile_username ON documents(lower(data->>'username')) WHERE kind='profile';
CREATE UNIQUE INDEX single_documents ON documents(owner_id,kind) WHERE kind IN('profile','goals','schedule','archives','hidden');
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO nlocki_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO nlocki_app;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE TABLE passkeys(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,public_key bytea NOT NULL,counter bigint NOT NULL,transports jsonb NOT NULL);
CREATE TABLE passkey_challenges(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,kind text NOT NULL,challenge text NOT NULL,expires bigint NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON passkeys,passkey_challenges TO nlocki_app;
-- Apply as the database administrator before updating an existing PostgreSQL beta stack.
CREATE TABLE IF NOT EXISTS consent_events(id bigserial PRIMARY KEY,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,version text NOT NULL,health_consent boolean NOT NULL,created timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON consent_events TO nlocki_app;
GRANT USAGE,SELECT ON SEQUENCE consent_events_id_seq TO nlocki_app;
